grep -i "converged" xtb1.log | tail -2; cat > conn.py << 'EOF'
import numpy as np, json
def read(p):
    L=open(p).read().split('\n'); n=int(L[0]); els=[];xyz=[]
    for line in L[2:2+n]:
        t=line.split(); els.append(t[0]); xyz.append([float(x) for x in t[1:4]])
    return els, np.array(xyz)
els,P=read('xtbopt.xyz')
cov={'H':0.31,'C':0.76,'N':0.71,'Ir':1.5,'Cd':1.5}
n=len(els)
adj={i:set() for i in range(n)}
for i in range(n):
    for j in range(i+1,n):
        d=np.linalg.norm(P[i]-P[j])
        if d < cov[els[i]]+cov[els[j]]+0.45:
            adj[i].add(j); adj[j].add(i)
# connected components
seen=set(); comps=[]
for i in range(n):
    if i in seen: continue
    st=[i]; seen.add(i); c=[]
    while st:
        u=st.pop(); c.append(u)
        for v in adj[u]:
            if v not in seen: seen.add(v); st.append(v)
    comps.append(c)
print("components:", len(comps), [len(c) for c in comps])
key=json.load(open('key.json'))
Ir=key['Ir']
print("Ir neighbors:", sorted((j, els[j], round(np.linalg.norm(P[Ir]-P[j]),2)) for j in adj[Ir]))
Cd=key['Cd']
print("Cd neighbors:", sorted((j, els[j], round(np.linalg.norm(P[Cd]-P[j]),2)) for j in adj[Cd]))
for c in key['carb']:
    print("carbene", c, "neighbors:", sorted((j,els[j]) for j in adj[c]))
EOF
python3 conn.py
